def hole_format_run(letter: str, count: int) -> str:
    """Return the encoded text for one run of `letter` repeated `count` times.

    Precondition: count >= 1 and letter is a single ASCII letter.
    Must return the letter alone when count == 1; otherwise it must return
    the letter immediately followed by the decimal representation of count
    (e.g. ('a', 3) -> 'a3', ('b', 1) -> 'b', ('a', 12) -> 'a12').
    """
    raise NotImplementedError

def hole_parse_count(s: str, pos: int) -> tuple[int, int]:
    """Read the optional run count that starts at index `pos` of encoded string `s`.

    `pos` is the index immediately after a letter. Must return a tuple
    (count, next_pos) where:
      - if one or more ASCII digits start at `pos`, count is their decimal
        value and next_pos is the index just past the last digit;
      - if no digit starts at `pos`, count is 1 and next_pos == pos.
    Must not read past the end of `s`.
    """
    raise NotImplementedError

def _is_letter(ch: str) -> bool:
    return len(ch) == 1 and ch.isascii() and ch.isalpha()

def compress(s: str) -> str:
    """Run-length encode a string of ASCII letters, e.g. 'aaabcc' -> 'a3bc2'."""
    for ch in s:
        if not _is_letter(ch):
            raise ValueError(f'compress: non-letter character {ch!r}')
    out = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        out.append(hole_format_run(s[i], j - i))
        i = j
    return ''.join(out)

def decompress(s: str) -> str:
    """Decode a run-length encoded string, e.g. 'a3bc2' -> 'aaabcc'."""
    out = []
    i = 0
    n = len(s)
    while i < n:
        letter = s[i]
        if not _is_letter(letter):
            raise ValueError(f'decompress: expected letter at index {i}, got {letter!r}')
        count, i = hole_parse_count(s, i + 1)
        out.append(letter * count)
    return ''.join(out)

def check_invariants() -> None:
    assert compress('') == ''
    assert compress('aaabcc') == 'a3bc2'
    assert compress('abc') == 'abc'
    assert compress('aaaaaaaaaaaa') == 'a12'
    assert decompress('') == ''
    assert decompress('a3bc2') == 'aaabcc'
    assert decompress(compress('zzzyyxw')) == 'zzzyyxw'


