def hole_c_div(a: int, b: int) -> int:
    """Return a / b as an int, truncated toward zero (C semantics)."""
    if b == 0:
        raise ZeroDivisionError('division by zero')
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b > 0) else -q

def hole_c_mod(a: int, b: int) -> int:
    """Return the remainder of a divided by b with C semantics."""
    if b == 0:
        raise ZeroDivisionError('modulo by zero')
    return a - b * hole_c_div(a, b)

def hole_pow(base: int, exponent: int) -> int:
    """Return base raised to exponent as an int."""
    if exponent < 0:
        raise ValueError('negative exponent is not supported for integer results')
    return base ** exponent

