from typing import Any, Callable, List, Optional, Sequence, Tuple
Parser = Callable[[str, int], Optional[Tuple[Any, int]]]
_FAILURES: List[int] = []

class ParseError(Exception):
    """Raised by parse() when input cannot be fully parsed."""

    def __init__(self, message: str, pos: int):
        super().__init__(f'{message} at position {pos}')
        self.pos = pos

def _record_failure(i: int) -> None:
    _FAILURES.append(i)
    return None

def hole_error_position(candidates: Sequence[int]) -> int:
    """Choose the position to report in a ParseError for a failed parse.

    `candidates` is a non-empty list of input indices at which primitive
    parsers failed during the attempt (it may contain duplicates, in any
    order). Return a single int index into the input that should be reported
    as the error position. Must not mutate `candidates`. Must return an
    element of `candidates`.
    """
    raise NotImplementedError

def hole_many_loop(p: Parser, s: str, i: int) -> Optional[Tuple[List[Any], int]]:
    """Apply `p` repeatedly starting at index `i` in `s` and collect results.

    Return a tuple (values, new_i) where `values` is the list of every value
    produced by successful applications of `p`, in order, and `new_i` is the
    index immediately after the last consumed application. Stop at the first
    application where `p` returns None. An application that succeeds without
    advancing the index (new_i == current index) must not be collected and must
    stop the loop, so the function always terminates. Always returns a tuple
    (never None); zero matches yields ([], i).
    """
    raise NotImplementedError

def satisfy(pred: Callable[[str], bool]) -> Parser:
    """Parser that consumes one character c at index i if pred(c) is true."""

    def p(s: str, i: int):
        if i < len(s) and pred(s[i]):
            return (s[i], i + 1)
        return _record_failure(i)
    return p

def char(c: str) -> Parser:
    """Parser matching exactly the single character `c`."""
    if len(c) != 1:
        raise ValueError('char() expects a single character')
    return satisfy(lambda x: x == c)

def string(t: str) -> Parser:
    """Parser matching the literal substring `t`, returning `t`."""

    def p(s: str, i: int):
        if s.startswith(t, i):
            return (t, i + len(t))
        return _record_failure(i)
    return p

def seq(*ps: Parser) -> Parser:
    """Run parsers in order; return the list of their values."""

    def p(s: str, i: int):
        values = []
        for q in ps:
            r = q(s, i)
            if r is None:
                return None
            v, i = r
            values.append(v)
        return (values, i)
    return p

def alt(*ps: Parser) -> Parser:
    """Return the result of the first parser that succeeds, else None."""

    def p(s: str, i: int):
        for q in ps:
            r = q(s, i)
            if r is not None:
                return r
        return None
    return p

def many(p: Parser) -> Parser:
    """Zero or more applications of `p`; returns a list of values."""

    def q(s: str, i: int):
        return hole_many_loop(p, s, i)
    return q

def sep_by(p: Parser, sep: Parser) -> Parser:
    """Zero or more `p` separated by `sep`; returns a list of `p` values."""

    def q(s: str, i: int):
        first = p(s, i)
        if first is None:
            return ([], i)
        vals = [first[0]]
        i = first[1]
        while True:
            r = seq(sep, p)(s, i)
            if r is None:
                return (vals, i)
            pair, i = r
            vals.append(pair[1])
    return q

def map_(p: Parser, f: Callable[[Any], Any]) -> Parser:
    """Apply `f` to the value produced by `p`."""

    def q(s: str, i: int):
        r = p(s, i)
        if r is None:
            return None
        v, ni = r
        return (f(v), ni)
    return q

