    """Run `p` on all of `s`, requiring it to consume the entire input.

    Returns the parsed value. Raises ParseError (with .pos) on failure or if
    input remains unconsumed.
    """
    _FAILURES.clear()
    r = p(s, 0)
    if r is None:
        raise ParseError('no match', hole_error_position(_FAILURES or [0]))
    value, i = r
    if i != len(s):
        raise ParseError('unconsumed input', i)
