from typing import Any, Callable, Optional, Sequence

def hole_alt(parsers: Sequence[Parser], s: str, i: int) -> Optional[tuple[Any, int]]:
    """Ordered choice at position i of input s.

    Try each parser in `parsers`, in order, applied to (s, i). Return the exact
    result tuple (value, new_i) of the first parser that does not return None.
    If every parser returns None, return None. Do not modify or reinterpret
    the successful result.
    """
    for p in parsers:
        r = p(s, i)
        if r is not None:
            return r
    return None

def hole_many(p: Parser, s: str, i: int) -> tuple[list[Any], int]:
    """Greedy zero-or-more repetition of p starting at position i of input s.

    Repeatedly apply p, appending each value to a list and advancing the
    position to the returned new_i. Stop when p returns None. If p succeeds
    without advancing the position (new_i equal to the current position),
    stop and do NOT include that value.

    Always returns a tuple (values, new_i). Never returns None. With zero
    matches the result is ([], i).
    """
    values: list[Any] = []
    pos = i
    while True:
        r = p(s, pos)
        if r is None:
            break
        v, j = r
        if j == pos:
            break
        values.append(v)
        pos = j
    return (values, pos)

def hole_sep_by(p: Parser, sep: Parser, s: str, i: int) -> tuple[list[Any], int]:
    """Zero-or-more occurrences of p separated by sep, starting at position i.

    First try p at i. If it fails, return ([], i). Otherwise collect its value
    and repeatedly: try sep, then p. If either fails, stop. The separator's
    value is discarded, and a separator that is not followed by a successful p
    is not consumed. Return (values, new_i), where new_i is the position right
    after the last successful p.

    Always returns a tuple. Never returns None.
    """
    first = p(s, i)
    if first is None:
        return ([], i)
    v, pos = first
    values: list[Any] = [v]
    while True:
        rs = sep(s, pos)
        if rs is None:
            break
        _, after_sep = rs
        rp = p(s, after_sep)
        if rp is None:
            break
        v, pos = rp
        values.append(v)
    return (values, pos)

