def _available_colors(node: Node, assignment: Assignment, adj: Adjacency, k: int) -> List[int]:
    """Colors in range(k) not used by any already-colored neighbor of `node`."""
    used = {assignment[v] for v in adj.get(node, ()) if v in assignment}
    return [c for c in range(k) if c not in used]

def hole_precoloring_consistent(adj: Adjacency, fixed: Assignment, k: int) -> bool:
    """Return True iff the precolored assignment is usable as a starting point:
    every fixed color lies in range(k) (0 <= c < k), and no two adjacent nodes
    that are both precolored share the same color. Return False otherwise.
    Must not modify its arguments."""
    for u, nbrs in adj.items():
        if u in nbrs:
            return False
    for c in fixed.values():
        if not isinstance(c, int) or isinstance(c, bool) or (not 0 <= c < k):
            return False
    for u, c in fixed.items():
        for v in adj.get(u, ()):
            if v in fixed and fixed[v] == c:
                return False
    return True

def hole_pick_next_node(free: List[Node], assignment: Assignment, adj: Adjacency, k: int) -> Node:
    """Return one node from the non-empty list `free` (uncolored nodes) to color
    next. Must be an element of `free`. The choice is a search-ordering policy
    and affects only speed, never correctness. Must not modify its arguments."""
    best: Optional[Node] = None
    best_key: Optional[Tuple[int, int]] = None
    for n in free:
        key = (len(_available_colors(n, assignment, adj, k)), -len(adj.get(n, ())))
        if best_key is None or key < best_key:
            best, best_key = (n, key)
    return best

def hole_solve(adj: Adjacency, assignment: Assignment, free: List[Node], k: int, pick: PickFn) -> Optional[Assignment]:
    """Extend `assignment` (which already fixes some nodes and is consistent)
    so that every node in `free` receives a color in range(k), with no edge in
    `adj` joining two nodes of equal color. Use `pick(free, assignment, adj, k)`
    to choose which free node to color next. Return a NEW dict containing all of
    `assignment` plus all of `free` colored, or None if no extension exists.
    Must not mutate `assignment` or `free`."""
    if not free:
        return dict(assignment)
    node = pick(free, assignment, adj, k)
    rest = [n for n in free if n != node]
    used_colors = set(assignment.values())
    unused_colors = [c for c in range(k) if c not in used_colors]
    first_unused = unused_colors[0] if unused_colors else None
    for c in _available_colors(node, assignment, adj, k):
        if c not in used_colors and c != first_unused:
            continue
        new_assignment = dict(assignment)
        new_assignment[node] = c
        if any((not _available_colors(n, new_assignment, adj, k) for n in rest)):
            continue
        result = hole_solve(adj, new_assignment, rest, k, pick)
        if result is not None:
            return result
    return None

