import re
from functools import cmp_to_key
_SEMVER_RE = re.compile('(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\\+([0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*))?')

def _parse(version):
    """Validate and split a version string into (major, minor, patch, prerelease_ids).

    Build metadata is validated but discarded, since it does not affect precedence.
    """
    if not isinstance(version, str):
        raise ValueError(f'version must be a string, got {type(version).__name__}')
    m = _SEMVER_RE.fullmatch(version)
    if m is None:
        raise ValueError(f'invalid semantic version: {version!r}')
    major, minor, patch, pre = (m.group(1), m.group(2), m.group(3), m.group(4))
    pre_ids = tuple(pre.split('.')) if pre else ()
    return (int(major), int(minor), int(patch), pre_ids)

def hole_compare_identifiers(x: str, y: str) -> int:
    """Compare two dot-separated pre-release identifiers (SemVer 11.4.1-11.4.2).

    Must return -1 if x has lower precedence than y, 0 if equal, 1 if higher.
    Rules to implement:
      - Identifiers consisting only of digits are compared numerically.
      - Alphanumeric identifiers are compared lexically in ASCII sort order.
      - Numeric identifiers always have lower precedence than alphanumeric ones.
    Both inputs are already validated, so no error handling is required.
    """
    raise NotImplementedError

def hole_compare_prerelease(pa: tuple[str, ...], pb: tuple[str, ...]) -> int:
    """Compare two pre-release identifier tuples (SemVer 11.3 and 11.4.4).

    Inputs are the pre-release identifiers of two versions whose major, minor
    and patch numbers are already known to be equal. An empty tuple means no
    pre-release part. Must return -1, 0 or 1 for pa < pb, pa == pb, pa > pb.
    Rules to implement:
      - A version with no pre-release has HIGHER precedence than one with a pre-release.
      - When both are non-empty, compare identifier by identifier using
        hole_compare_identifiers; the first difference decides.
      - If all shared identifiers are equal, the longer tuple has higher precedence.
    """
    raise NotImplementedError

def compare_versions(a: str, b: str) -> int:
    """Return -1 if a < b, 0 if a == b, 1 if a > b under SemVer 2.0.0 precedence.

    Raises ValueError if either argument is not a valid semantic version.
    """
    pa = _parse(a)
    pb = _parse(b)
    core_a, core_b = (pa[:3], pb[:3])
    if core_a != core_b:
        return -1 if core_a < core_b else 1
    return hole_compare_prerelease(pa[3], pb[3])

def sort_versions(versions) -> list[str]:
    """Return a new list of the given versions sorted in ascending precedence.

    Raises ValueError if any element is an invalid semantic version, even when
    the input has only one element.
    """
    items = list(versions)
    for v in items:
        _parse(v)
    return sorted(items, key=cmp_to_key(compare_versions))

